import{_ as a}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as r}from"./chunks/fw_goto_altitude_foh.BcCcrFcD.js";import{_ as l,C as n,o as s,c as d,al as i,E as o,a as h}from"./chunks/framework.7vp1BMOE.js";const k=JSON.parse('{"title":"Hold Mode (Fixed-Wing)","description":"","frontmatter":{},"headers":[],"relativePath":"en/flight_modes_fw/hold.md","filePath":"en/flight_modes_fw/hold.md"}'),m={name:"en/flight_modes_fw/hold.md"};function c(_,e,p,u,g,f){const t=n("Badge");return s(),d("div",null,[e[0]||(e[0]=i('<h1 id="hold-mode-fixed-wing" tabindex="-1">Hold Mode (Fixed-Wing) <a class="header-anchor" href="#hold-mode-fixed-wing" aria-label="Permalink to &quot;Hold Mode (Fixed-Wing)&quot;">​</a></h1><img src="'+a+'" title="Position fix required (e.g. GPS)" width="30px"><p>The <em>Hold</em> flight mode causes the vehicle to loiter around its current GPS position and maintain its current altitude.</p><p>The mode supports a <a href="#loiter-modes">number of distinct loiter modes</a>, which are triggered using different QGC controls or MAVLink commands. These allow loitering with circular and figure 8 flight paths.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><em>Hold mode</em> can be used to pause a mission or to help you regain control of a vehicle in an emergency. It is usually activated with a pre-programmed RC switch.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Mode is automatic - no user intervention is <em>required</em> to control the vehicle.</li><li>Mode requires a global 3d position estimate (from GPS or inferred from a <a href="./../ros/external_position_estimation#enabling-auto-modes-with-a-local-position">local position</a>). <ul><li>Flying vehicles can&#39;t switch to this mode without global position.</li><li>Flying vehicles will failsafe if they lose the position estimate.</li><li>Disarmed vehicles can switch to mode without valid position estimate but can&#39;t arm.</li></ul></li><li>Mode requires wind and flight time are within allowed limits (specified via parameters).</li><li>RC control switches can be used to change flight modes on any vehicle.</li><li>RC stick movement is ignored.</li></ul></div><h2 id="loiter-modes" tabindex="-1">Loiter modes <a class="header-anchor" href="#loiter-modes" aria-label="Permalink to &quot;Loiter modes&quot;">​</a></h2><h3 id="default-loiter" tabindex="-1">Default Loiter <a class="header-anchor" href="#default-loiter" aria-label="Permalink to &quot;Default Loiter&quot;">​</a></h3><p>The aircraft circles around the position at which the mode was triggered and maintain its current altitude. The loiter radius is set by the parameter <a href="#NAV_LOITER_RAD">NAV_LOITER_RAD</a>. Note that if the vehicle altitude is below <a href="#NAV_MIN_LTR_ALT">NAV_MIN_LTR_ALT</a>, it will ascend to that minimum altitude before circling.</p><p>The default loiter mode is entered when you switch to Hold mode without explicitly specifying any loiter behaviour. For example, if you switch to Hold mode using an RC switch, select <strong>Hold</strong> on the QGC flight mode selector, or activate the mode using the MAVLink <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_SET_MODE" target="_blank" rel="noreferrer">MAV_CMD_DO_SET_MODE</a> command.</p><h3 id="orbit-loiter-mode" tabindex="-1">Orbit Loiter Mode <a class="header-anchor" href="#orbit-loiter-mode" aria-label="Permalink to &quot;Orbit Loiter Mode&quot;">​</a></h3>',11)),o(t,{type:"tip",text:"PX4 v1.12"}),e[1]||(e[1]=i('<p>The aircraft travels towards a <em>specified</em> orbit center position, then circles it with a given direction and radius.</p><p>This behaviour can be accessed in QGroundControl by clicking on the map in Fly view, selecting <strong>Orbit at Location</strong>, and configuring the radius.</p><p>The behavior can be triggered using the MAVLink <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_ORBIT" target="_blank" rel="noreferrer">MAV_CMD_DO_ORBIT</a> command. Note that PX4 respects the specified centre point (<code>param5</code>, <code>param6</code>, <code>param7</code>), and the radius and direction (<code>param1</code>). PX4 ignores <code>param3</code> (Yaw behaviour) and <code>param4</code> (Orbits). The value of <code>param2</code> (velocity) is also ignored, but the speed can be controlled using the <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_CHANGE_SPEED" target="_blank" rel="noreferrer">MAV_CMD_DO_CHANGE_SPEED</a> command (constrained between <code>FW_AIRSPD_MAX</code> and <code>FW_AIRSPD_MIN</code>). PX4 outputs orbit status using the <a href="https://mavlink.io/en/messages/common.html#ORBIT_EXECUTION_STATUS" target="_blank" rel="noreferrer">ORBIT_EXECUTION_STATUS</a> message.</p><h3 id="figure-8-loiter-mode" tabindex="-1">Figure 8 Loiter Mode <a class="header-anchor" href="#figure-8-loiter-mode" aria-label="Permalink to &quot;Figure 8 Loiter Mode&quot;">​</a></h3>',4)),o(t,{type:"tip",text:"PX4 v1.15"}),e[2]||(e[2]=h()),o(t,{type:"warning",text:"Experimental"}),e[3]||(e[3]=i('<p>The aircraft flys towards the closest point on a specified figure 8 path and then follows it. The path is defined by the figure 8 centre position, orientation, and radius of two circles.</p><p>The feature is experimental, and is not present in PX4 firmware by default (on most flight controller boards). It can be included by setting the <code>CONFIG_FIGURE_OF_EIGHT</code> key in the <a href="./../hardware/porting_guide_config#px4-board-configuration-kconfig">PX4 board configuration</a> for your board and rebuilding. For example, this is enabled on the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/auterion/fmu-v6s/default.px4board#L46" target="_blank" rel="noreferrer">default.px4board</a> file for the <code>auterion/fmu-v6s</code> board.</p><p>The behavior can be triggered using the MAVLink <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_FIGURE_EIGHT" target="_blank" rel="noreferrer">MAV_CMD_DO_FIGURE_EIGHT</a> command (PX4 respects all the parameters). PX4 outputs the figure 8 status using the <a href="https://mavlink.io/en/messages/common.html#FIGURE_EIGHT_EXECUTION_STATUS" target="_blank" rel="noreferrer">FIGURE_EIGHT_EXECUTION_STATUS</a> message.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Figure 8 loitering is not currently supported by QGC: <a href="https://github.com/mavlink/qgroundcontrol/issues/12778" target="_blank" rel="noreferrer">QGC#12778: Need Support Figure of eight (8 figure) loitering by QGC</a>.</p></div><p>Figure 8 loitering is also available in the simulator. You can test it in <a href="./../sim_gazebo_gz/">Gazebo</a> using a fixed wing frame:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_rc_cessna</span></span></code></pre></div><h2 id="altitude-ramp-on-reposition-go-to" tabindex="-1">Altitude Ramp on Reposition (Go-to) <a class="header-anchor" href="#altitude-ramp-on-reposition-go-to" aria-label="Permalink to &quot;Altitude Ramp on Reposition (Go-to)&quot;">​</a></h2><p>When you command the vehicle to a new loiter location at a different altitude — for example a QGroundControl <em>Go to location</em> / <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_REPOSITION" target="_blank" rel="noreferrer">reposition</a> while in Hold mode — PX4 does not change the altitude setpoint in a single step. Instead it ramps the altitude setpoint linearly (a first order hold, FOH) from the vehicle&#39;s <strong>current altitude</strong> to the new target altitude, reaching the target by the time the vehicle arrives at the loiter circle around the new location. The result is a smooth diagonal climb or descent along the transit to the new location, rather than an immediate climb/descent followed by level flight.</p><p><img src="'+r+'" alt="Fixed-wing altitude profile for a climbing go-to in Hold mode"></p><p>The ramp is anchored at the altitude the vehicle is at when the new target is received, and its progress is measured by the vehicle&#39;s horizontal approach to the target (not by time).</p><p>If the vehicle cannot follow the ramp (for example when the required climb or sink rate exceeds what the aircraft can achieve), the altitude setpoint still reaches the full target altitude at the loiter circle. Any remaining altitude error is then removed by climbing or sinking once the vehicle reaches the horizontal position of the new location.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The ramp is (re)started whenever the target altitude changes; a reposition that keeps the same altitude does not change the vehicle&#39;s altitude.</p></div><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_global_position_relaxed"><code>mode_req_global_position_relaxed</code></a> — Position measurement updates in a global coordinate frame but accepts poor accuracy</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_position_relaxed"><code>mode_req_local_position_relaxed</code></a> — Position relative to EKF2 origin (&#39;0&#39;) point but accepts poor accuracy</li><li><a href="./../flight_modes/mode_requirements#mode_req_wind_and_flight_time_compliance"><code>mode_req_wind_and_flight_time_compliance</code></a> — Safety compliance limits on wind and flight time.</li></ul><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><p>Hold mode behaviour can be configured using the parameters below.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><a id="NAV_LOITER_RAD"></a><a href="./../advanced_config/parameter_reference#NAV_LOITER_RAD">NAV_LOITER_RAD</a></td><td>The radius of the loiter circle.</td></tr><tr><td><a id="NAV_MIN_LTR_ALT"></a><a href="./../advanced_config/parameter_reference#NAV_MIN_LTR_ALT">NAV_MIN_LTR_ALT</a></td><td>Minimum height for loiter mode (vehicle will ascend to this altitude if mode is engaged at a lower altitude).</td></tr></tbody></table><h2 id="mavlink-commands" tabindex="-1">MAVLink Commands <a class="header-anchor" href="#mavlink-commands" aria-label="Permalink to &quot;MAVLink Commands&quot;">​</a></h2><p>The following commands are relevant to this mode:</p><ul><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_ORBIT" target="_blank" rel="noreferrer">MAV_CMD_DO_ORBIT</a> - Switch to Hold mode and start the specified <a href="#orbit-loiter-mode">Orbit loiter</a>. Params 2 (velocity), 3 (yaw), 4 (orbits) are ignored. <a href="https://mavlink.io/en/messages/common.html#ORBIT_EXECUTION_STATUS" target="_blank" rel="noreferrer">ORBIT_EXECUTION_STATUS</a> is emitted.</li><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_FIGURE_EIGHT" target="_blank" rel="noreferrer">MAV_CMD_DO_FIGURE_EIGHT</a> - Switch to Hold mode and start the specified <a href="#figure-8-loiter-mode">Figure 8 loiter</a>. All params are respected. <a href="https://mavlink.io/en/messages/common.html#FIGURE_EIGHT_EXECUTION_STATUS" target="_blank" rel="noreferrer">FIGURE_EIGHT_EXECUTION_STATUS</a> is emitted.</li></ul><p>Note, other commands may be supported.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../flight_modes_mc/hold">Hold Mode (MC)</a></li></ul>',24))])}const A=l(m,[["render",c]]);export{k as __pageData,A as default};
